import{_ as e,o as i,c as l,e as t}from"./app-6be1f847.js";const s={},r=t('<h3 id="及物动词-vs-不及物动词-vs-不完全不及物动词" tabindex="-1"><a class="header-anchor" href="#及物动词-vs-不及物动词-vs-不完全不及物动词" aria-hidden="true">#</a> 及物动词 vs 不及物动词 vs 不完全不及物动词</h3><ul><li>及物动词(Transitive Verbs)需要宾语来完成其意义。</li><li>不及物动词(Intransitive Verbs)不需要宾语，但可能需要其他成分如副词或介词短语来补充意义。</li><li>不完全不及物动词/系动词(Linking Verbs 或 Incomplete Intransitive Verbs)用于连接主语和描述主语特征的词语，形成主系表结构。</li></ul><p>不完全不及物动词，通常被称为连系动词（linking verbs）或状态动词，在英语中用于连接主语和提供关于主语更多信息的表语。这些动词本身意义不完整，需要一个补语来完成句子的意思。以下是一些常见的不完全不及物动词及其用法：</p><ol><li><p><strong>Be动词</strong>：这是最常见的连系动词，用来表示身份、特征、状态等。</p><ul><li>例如：She is a teacher. / He was tired after the long journey.</li></ul></li><li><p><strong>感官动词</strong>：这类动词包括look（看起来）、sound（听起来）、smell（闻起来）、taste（尝起来）、feel（感觉起来）。</p><ul><li>例如：The food tastes delicious. / That sounds like a great idea.</li></ul></li><li><p><strong>变化类动词</strong>：become, get, grow, turn, go, fall等动词用来描述从一种状态到另一种状态的变化。</p><ul><li>例如：He became angry at the news. / The leaves turned yellow in autumn.</li></ul></li><li><p><strong>似乎/显得类动词</strong>：seem, appear也属于这一类别。</p><ul><li>例如：It seems that we have a problem. / She appeared upset when I saw her.</li></ul></li><li><p><strong>保持类动词</strong>：keep, remain, stay等动词用来表示持续的状态。</p><ul><li>例如：Please keep quiet during the exam. / Despite the difficulties, he remained optimistic.</li></ul></li><li><p><strong>其他连系动词</strong>：如prove（证明是），turn out（结果是）等。</p><ul><li>例如：His prediction proved accurate. / The day turned out to be perfect for a picnic.</li></ul></li></ol><p>值得注意的是，一些动词既可以作为实义动词也可以作为连系动词使用。例如，“grow”可以指“生长”（实义动词）也可以表示“变得”（连系动词）。当它表示“变得”时，后面通常跟着形容词或名词作补语。 在使用这些动词时，重要的是要注意它们后接的补语类型。比如be动词后面可以接名词、形容词、介词短语等；而感官动词和其他类型的连系动词通常后面跟形容词或者名词形式的补语。</p>',5),o=[r];function n(a,p){return i(),l("div",null,o)}const c=e(s,[["render",n],["__file","/home/runner/work/vuepress_blog/vuepress_blog/docs/.vuepress/.temp/pages/english/english_core.html.vue"]]);export{c as default};
